import os
import sys
import numpy as np
import pandas as pd
from collections import defaultdict
from sklearn.model_selection import train_test_split

# Suppress warnings
import warnings

warnings.filterwarnings("ignore")


def main():
    # Robust file detection by scanning input directory
    input_dir = "./input"
    if not os.path.exists(input_dir):
        raise FileNotFoundError("Input directory ./input does not exist")

    # Find train, test, and sample CSV files
    available_files = [f for f in os.listdir(input_dir) if f.endswith(".csv")]

    train_file = None
    test_file = None
    sample_file = None

    for f in available_files:
        df_preview = pd.read_csv(f)
        if "before" in df_preview.columns and "after" in df_preview.columns:
            if (
                "class" in df_preview.columns
                or "sentence_id" in df_preview.columns
                and "token_id" in df_preview.columns
            ):
                if train_file is None:
                    train_file = f
                elif (
                    "sentence_id" in df_preview.columns
                    and "token_id" in df_preview.columns
                ):
                    test_file = f
        elif len(available_files) > 1 and (
            "sample" in f.lower() or "submission" in f.lower()
        ):
            sample_file = f

    # Fallback to common naming patterns if automatic detection fails
    if train_file is None:
        for f in available_files:
            if "train" in f.lower():
                train_file = f
                break

    if test_file is None:
        for f in available_files:
            if "test" in f.lower():
                test_file = f
                break

    if sample_file is None:
        for f in available_files:
            if "sample" in f.lower() or "submission" in f.lower():
                sample_file = f

    # Load data files with explicit error handling
    try:
        train_data = pd.read_csv(train_file) if train_file else None
        test_data = pd.read_csv(test_file) if test_file else None
        sample_submission = pd.read_csv(sample_file) if sample_file else None
    except Exception as e:
        print(f"Error loading data files: {e}")
        return None

    if train_data is None or test_data is None or sample_submission is None:
        print("Failed to load required files")
        return None

    # Create submission directory if needed
    os.makedirs("./submission", exist_ok=True)

    # Clean and construct id column for both datasets
    train_data["id"] = (
        train_data["sentence_id"].astype(str) + "_" + train_data["token_id"].astype(str)
    )
    test_data["id"] = (
        test_data["sentence_id"].astype(str) + "_" + test_data["token_id"].astype(str)
    )

    print(f"Train shape: {train_data.shape}, Test shape: {test_data.shape}")

    # Validate submission format against sample
    expected_format = sample_submission.columns.tolist()
    assert expected_format == ["id", "after"], f"Expected format {expected_format}"

    # PROPER HOLD-OUT EVALUATION: Split training data BEFORE any rule building
    # This ensures validation set is NEVER seen during training/rule generation
    train_valid_split = train_test_split(
        train_data.index,
        train_size=0.9,
        random_state=42,
        stratify=train_data["class"] if "class" in train_data.columns else None,
    )

    train_idx, valid_idx = train_valid_split

    train_set = train_data.iloc[train_idx].reset_index(drop=True)
    validation_set = train_data.iloc[valid_idx].reset_index(drop=True)

    print(f"Valid Split: Train={len(train_set)}, Validation={len(validation_set)}")

    # Build comprehensive normalization rules from TRAINING set ONLY
    before_to_after = {}

    # Vectorized operation for faster processing
    before_values = train_set["before"].fillna("").astype(str).tolist()
    after_values = train_set["after"].fillna("").astype(str).tolist()

    # Fill missing mappings with default (forward mapping)
    for i, (before_val, after_val) in enumerate(zip(before_values, after_values)):
        if before_val not in before_to_after:
            before_to_after[before_val] = after_val

    print(f"Built {len(before_to_after)} normalization rules from training set")

    # Evaluate on VALIDATION SET (data NOT used for rule training)
    val_predictions = []

    # Vectorized prediction on validation set
    val_before_vals = validation_set["before"].fillna("").astype(str).tolist()
    val_correct_count = 0

    for pred_before in val_before_vals:
        if pred_before in before_to_after:
            val_predictions.append(before_to_after[pred_before])
            if before_to_after[pred_before] == str(
                validation_set.iloc[
                    validation_set.index.get_loc(val_before_vals.index(val_before_vals))
                ]["after"]
            ):
                val_correct_count += 1
        else:
            val_predictions.append(pred_before)
            if pred_before == str(
                validation_set.iloc[
                    validation_set.index.get_loc(val_before_vals.index(val_before_vals))
                ]["after"]
            ):
                val_correct_count += 1

    # Calculate sequence-level accuracy
    val_accuracy = val_correct_count / len(validation_set) * 100

    print(f"Validation Set Accuracy: {val_accuracy:.4f}%")

    # Apply normalized rules to ACTUAL UNLABELED TEST DATA
    test_predictions = []

    # Vectorized prediction on test data
    test_before_vals = test_data["before"].fillna("").astype(str).tolist()

    for pred_before in test_before_vals:
        if pred_before in before_to_after:
            test_predictions.append(before_to_after[pred_before])
        else:
            test_predictions.append(pred_before)

    # Save predictions to required location
    submission_df = pd.DataFrame({"id": test_data["id"], "after": test_predictions})
    submission_df.to_csv("./submission/submission.csv", index=False)
    print(f"Submission saved to ./submission/submission.csv")
    print(f"Submission shape: {submission_df.shape}")
    print(f"Number of unique predictions: {submission_df['after'].nunique()}")

    return {"validation_metric": val_accuracy}


if __name__ == "__main__":
    result = main()
    if result:
        print(f"\nFinal Validation Metric: {result['validation_metric']:.2f}%")
